task eulerian_num(n: int, m: int) returns (r: int)
  requires n >= 0
  requires m >= 0
  requires m <= n
  ensures r == eulerian_number(n, m)
{
  var a: array[int, 0..n] := [0, 1, 0, 0, 0, 0];
  var i: int := 1;
  while i < n
    invariant 0 <= i and i <= n
    invariant forall j in [0, i) . a[j] == eulerian_number(i, j)
    decreases n - i
  {
    var j: int := 0;
    while j < i
      invariant 0 <= j and j < i
      invariant forall k in [0, j) . a[k] == eulerian_number(i, k)
      decreases i - j
    {
      a[i] := a[i] + (i - j) * a[j];
      j := j + 1;
    }
    a := a[i := a[i]];
    i := i + 1;
  }
  r := a[n];
}
